import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`sales rep: add a new lead with a name, company, and estimated deal value`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a rep adds a lead, every team member sees the new lead card in the first pipeline stage within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();

    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Sales rep (node 0) opens the Add Lead modal via the "+ Add Lead" toolbar button
      await pageA.getByRole('button', { name: '+ Add Lead' }).click();
      await expect(pageA.getByText('Add Lead')).toBeVisible({ timeout: 5_000 });

      // Fill in name, company, and estimated deal value
      await pageA.getByLabel('Lead / Contact Name').fill('E2E Test Lead');
      await pageA.getByLabel('Company').fill('Test Corp');
      await pageA.getByLabel('Estimated Deal Value ($)').fill('50000');

      // Submit — modal closes and lead lands in the first pipeline stage
      await pageA.getByRole('button', { name: 'Add Lead' }).click();

      // Sales rep's board shows the new lead card
      await expect(pageA.getByText('E2E Test Lead')).toBeVisible({ timeout: 5_000 });

      // Every team member (node 1) sees the new lead card within 5 s
      await expect(pageB.getByText('E2E Test Lead')).toBeVisible({ timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
